// Así está el servicio hoy. Cóbrale al primer pedido y mira la salida:
// eso es todo lo que tendrás cuando algo falle un domingo por la noche.

const pedidos = require('./pedidos');
const { cobrar } = require('./cobros');

const pedido = pedidos[0];

console.log('procesando pedido...');
cobrar(pedido);
console.log('ok');

// Los datos que llegan del checkout. No los toques: la lección es qué se
// hace con ellos, y lo que NO se hace (mirar los dos últimos campos).

module.exports = [
  { id: 'A-1042', cliente: 'ana@ejemplo.com', total: 39.9, tarjeta: '4242 4242 4242 4242' },
  { id: 'A-1043', cliente: 'luis@ejemplo.com', total: 149.5, tarjeta: '4000 0000 0000 0002' },
];

// La pasarela de pago, simulada. Por encima de 100 € pide autorización
// manual, así que falla.

function cobrar(pedido) {
  if (pedido.total > 100) {
    throw new Error('limite superado');
  }
  return { referencia: 'ref-' + pedido.id };
}

module.exports = { cobrar };

// Paso 3: aquí vive el logger. Ahora mismo no exporta nada.
//
// Tiene que poner el sello de tiempo y el nombre del servicio por su
// cuenta: si eso depende de acordarse en cada llamada, alguien no se
// acordará, y será justo la línea que hacía falta.

