const pedidos = require('./pedidos');
const { cobrar } = require('./cobros');

const pedido = pedidos[0];
const resultado = cobrar(pedido);

console.log(
  JSON.stringify({
    level: 'info',
    event: 'pedido_cobrado',
    pedidoId: pedido.id,
    total: pedido.total,
    referencia: resultado.referencia,
  }),
);

const pedidos = require('./pedidos');
const { cobrar } = require('./cobros');

for (const pedido of pedidos) {
  try {
    const resultado = cobrar(pedido);
    console.log(
      JSON.stringify({
        level: 'info',
        event: 'pedido_cobrado',
        pedidoId: pedido.id,
        total: pedido.total,
        referencia: resultado.referencia,
      }),
    );
  } catch (error) {
    console.log(
      JSON.stringify({
        level: 'error',
        event: 'cobro_fallido',
        pedidoId: pedido.id,
        motivo: error.message,
      }),
    );
  }
}

function log(level, event, datos) {
  console.log(
    JSON.stringify({
      ts: new Date().toISOString(),
      service: 'cobros',
      level: level,
      event: event,
      ...datos,
    }),
  );
}

module.exports = { log };

const pedidos = require('./pedidos');
const { cobrar } = require('./cobros');
const { log } = require('./log');

for (const pedido of pedidos) {
  try {
    const resultado = cobrar(pedido);
    log('info', 'pedido_cobrado', {
      pedidoId: pedido.id,
      total: pedido.total,
      referencia: resultado.referencia,
    });
  } catch (error) {
    log('error', 'cobro_fallido', { pedidoId: pedido.id, motivo: error.message });
  }
}

